from pathlib import Path
from PIL import Image
import json, html, re, markdown, hashlib, xml.etree.ElementTree as ET
P=Path(__file__).resolve().parent.parent
E=html.escape
(P/'thumbnails').mkdir(exist_ok=True)
public=[];app=[];excluded=[]
for f in sorted((P/'screenshots').glob('*.png')):
 evidence=P/'raw/styles'/(f.stem+'-styles.json')
 if not evidence.exists():continue
 d=json.loads(evidence.read_text())
 if not isinstance(d,dict):continue
 public.append({'name':f.stem,'title':d['title'],'url':d['url'],'file':str(f.relative_to(P)),'type':'Public','evidence':str(evidence.relative_to(P))})
# The signed-in screenshots were removed because they showed a real workspace. The anonymised
# accessibility snapshots stay, so app screens are listed from them and carry no image.
for snap in sorted((P/'screenshots/app').glob('*.txt')):
 f=snap;s=snap.read_text()
 m=re.search(r'HTML content (.+?), URL: ([^\n]+)',s)
 if f.stem.startswith('settings-'):
  if 'chrome-error://' in s or (m and '/settings/' in m[2] and m[2].split('/settings/')[1].replace('/','-')!=f.stem[9:]):
   excluded.append({'name':f.stem,'reason':'Destination redirected or did not load; screenshot omitted from gallery','observed':m[0] if m else ''});continue
 app.append({'name':f.stem,'title':m[1] if m else f.stem,'url':('https://'+m[2]) if m and m[2].startswith('linear.app') else None,'type':'App','evidence':str(snap.relative_to(P))})
for item in public:
 im=Image.open(P/item['file']).convert('RGB');im=im.crop((0,0,im.width,min(im.height,round(im.width*.7))));im.thumbnail((480,336));thumb='thumbnails/'+item['type'].lower()+'-'+item['name']+'.jpg';im.save(P/thumb,quality=85);item['thumbnail']=thumb
coverage={'date':'2026-09-23','refreshed':'2026-10-17','scope':'Page types and primary public navigation, not all nested routes or records; the signed-in app re-measured in dark and light on 2026-10-17 (README coverage table)','public':public,'app':app,'appMeasured':sorted(str(f.relative_to(P)) for f in (P/'screenshots/app-2026-10').glob('*.png')),'excluded':excluded,'gaps':['Checkbox visible state (shown by script only)','Radio (not present on the screens scanned)','Disabled controls (none appeared)','Validation error, destructive confirmation, loading and error states (need actions this capture does not take)','Onboarding','Issue list layout and the command menu','All nested public articles and documentation','Credential/security settings','Enabled cycles and triage','Native Figma/Paper import verification']}
(P/'raw/coverage.json').write_text(json.dumps(coverage,indent=2))
