report={'publicCaptures':len(public),'appSnapshots':len(app),'components':len(components),'referenceIcons':len(iconfiles),'boards':len(boards),'svgParseErrors':errors,'nativeEditorImport':'Not tested','browserRender':'Pending visual review'}
