# Content-version vector URLs so a rebuilt guide cannot display cached drawings.
for page_name in ['style-guide.html','preview.html']:
 f=P/page_name
 def version_svg(match):
  relative=match.group(2)
  digest=hashlib.sha256((P/relative).read_bytes()).hexdigest()[:12]
  return match.group(1)+relative+'?v='+digest+'"'
 f.write_text(re.sub(r'((?:src|href)=")([^"?]+\.svg)"',version_svg,f.read_text()))
